package fr.proutlost.worldprep.plan;
import fr.proutlost.worldprep.persistence.WorldPrepSavedData;
/** Only complete 4x4 biome cells are writable, preventing changes outside block bounds. */
public record BiomeBounds(int minQuartX,int minQuartZ,int maxQuartX,int maxQuartZ){public static BiomeBounds inside(WorldPrepSavedData.Area a){int minX=Math.floorDiv(a.minX()+3,4),minZ=Math.floorDiv(a.minZ()+3,4),maxX=Math.floorDiv(a.maxX()-3,4),maxZ=Math.floorDiv(a.maxZ()-3,4);if(minX>maxX||minZ>maxZ)throw new IllegalArgumentException("Area contains no complete biome cell");return new BiomeBounds(minX,minZ,maxX,maxZ);}public long width(){return(long)maxQuartX-minQuartX+1;}public long cells(){return width()*((long)maxQuartZ-minQuartZ+1);}public boolean contains(int qx,int qz){return qx>=minQuartX&&qx<=maxQuartX&&qz>=minQuartZ&&qz<=maxQuartZ;}public boolean footprintInside(WorldPrepSavedData.Area a,int qx,int qz){int x=qx<<2,z=qz<<2;return x>=a.minX()&&x+3<=a.maxX()&&z>=a.minZ()&&z+3<=a.maxZ();}}
